def word_counts(sentence):
    counts = {}
    for word in sentence.lower().split():
        word = word.strip(".,!?")
        counts[word] = counts.get(word, 0) + 1
    return counts

result = word_counts("The cat sat. The cat ran! A dog sat.")
for word, n in sorted(result.items(), key=lambda pair: (-pair[1], pair[0])):
    print(word, n)
